  border-radius: 7px;
  padding: 2px 7px;
}

pre code {
  border: 0;
  background: transparent;
  padding: 0;
  border-radius: 0;
  font-size: inherit;
  color: inherit;
}

.prose pre {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #1d2e45;
  color: #e8efff;
}

.page-wrap {
  width: min(1080px, calc(100% - 2rem));
  margin-inline: auto;
}

.display-title {
  font-family: 'Fraunces', Georgia, serif;
}

.island-shell {
  border: 1px solid var(--line);
  background: linear-gradient(165deg, var(--surface-strong), var(--surface));
  box-shadow:
    0 1px 0 var(--inset-glint) inset,
    0 22px 44px rgba(30, 90, 72, 0.1),
    0 6px 18px rgba(23, 58, 64, 0.08);
  backdrop-filter: blur(4px);
}

.feature-card {
  background: linear-gradient(165deg, color-mix(in oklab, var(--surface-strong) 93%, white 7%), var(--surface));
  box-shadow:
    0 1px 0 var(--inset-glint) inset,
    0 18px 34px rgba(30, 90, 72, 0.1),
    0 4px 14px rgba(23, 58, 64, 0.06);
}

.feature-card:hover {
  transform: translateY(-2px);
  border-color: color-mix(in oklab, var(--lagoon-deep) 35%, var(--line));
}

button,
.island-shell,
a {
  transition: background-color 180ms ease, color 180ms ease, border-color 180ms ease,
    transform 180ms ease;
}

.island-kicker {
  letter-spacing: 0.16em;
  text-transform: uppercase;
  font-weight: 700;
  font-size: 0.69rem;
  color: var(--kicker);
}

.nav-link {
  position: relative;
  text-decoration: none;
  color: var(--sea-ink-soft);
}

.nav-link::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -8px;
  width: 100%;
  height: 2px;
  transform: scaleX(0);
  transform-origin: left;
  background: linear-gradient(90deg, var(--lagoon), #7ed3bf);
  transition: transform 170ms ease;
}

.nav-link:hover,
.nav-link.is-active {
  color: var(--sea-ink);
}

.nav-link:hover::after,
.nav-link.is-active::after {
  transform: scaleX(1);
}

.rise-in {
  animation: rise-in 700ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes rise-in {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.site-footer {
  border-top: 1px solid var(--line);
  background: color-mix(in oklab, var(--header-bg) 84%, transparent 16%);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    background-color: var(--background);
    color: var(--foreground);
  }
}
